<script>
(function(){
  function fill(text){
    if(!text || !text.trim()) return;
    try {
      var input = window.parent.document.querySelector('#send_textarea');
      if(!input) return;
      var cur = (input.value || '').trim();
      input.value = cur ? (cur + '\n' + text) : text;
      input.dispatchEvent(new Event('input', { bubbles: true }));
      input.focus();
    } catch(e) {}
  }
  function onClick(e){
    var link = e.target.closest && e.target.closest('.liwe-opt');
    if(!link) return;
    var t = link.getAttribute('data-option-text') || '';
    fill(t.trim());
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){
      document.addEventListener('click', onClick);
    });
  } else {
    document.addEventListener('click', onClick);
  }
})();
</script>
